3	/**
4	 * Computes the Luhn check digit over the decimal digits contained in a value, ignoring any
5	 * non-digit characters (such as the separators in a customer code). A pure function of the value,
6	 * so it is derived at response time rather than stored on the entity.
7	 */
8	public final class CheckDigit {
9	
10	    private CheckDigit() {
11	    }
12	
13	    /**
14	     * The Luhn check digit (0-9) over the digits in {@code value}, or {@code null} when
15	     * {@code value} is {@code null}.
16	     */
17	    public static Integer of(String value) {
18	        if (value == null) {
19	            return null;
20	        }
21	        int sum = 0;
22	        boolean doubling = true;
23	        for (int i = value.length() - 1; i >= 0; i--) {
24	            char c = value.charAt(i);
25	            if (c < '0' || c > '9') {
26	                continue;
27	            }
28	            int digit = c - '0';
29	            if (doubling) {
30	                digit *= 2;
31	                if (digit > 9) {
32	                    digit -= 9;
33	                }
34	            }
35	            sum += digit;
36	            doubling = !doubling;
37	        }
38	        return (10 - (sum % 10)) % 10;
39	    }
40	}
