5	/**
6	 * Derives an owner's membership level, a number from 1 to 3 fixed at the moment the owner is
7	 * created. It starts at 1, gains 1 when an email address is present, and gains 1 when the owner has
8	 * a unique name (namesakeCount is zero), capped at 3. Level 4 is reserved for tenure. Pure function
9	 * of the owner's own fields, so it is derived at response time rather than stored on the entity.
10	 */
11	public final class MembershipLevel {
12	
13	    /** The lowest membership level every owner starts from. */
14	    public static final int BASE = 1;
15	
16	    /** The highest level this rule awards; level 4 is reserved for tenure. */
17	    public static final int CAP = 3;
18	
19	    private MembershipLevel() {
20	    }
21	
22	    /** The membership level for {@code owner}, or {@code null} when the owner is {@code null}. */
23	    public static Integer of(Owner owner) {
24	        if (owner == null) {
25	            return null;
26	        }
27	        int level = BASE;
28	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
29	            level++;
30	        }
31	        Integer namesakeCount = owner.getNamesakeCount();
32	        if (namesakeCount != null && namesakeCount == 0) {
33	            level++;
34	        }
35	        return Math.min(level, CAP);
36	    }
37	}
