5	/**
6	 * The single derived duplicate-detection key for owners: the canonical telephone, the canonical email
7	 * (empty when absent) and the household id (empty when the owner is in no shared household), joined by
8	 * '|'. {@link EnsureUniqueIdentity} rejects a create request whose whole key equals an existing
9	 * owner's, and {@link org.springframework.samples.petclinic.mapper.OwnerMapper} returns it on the
10	 * response. Consolidating telephone, email and household into one key means two owners collide only on
11	 * an exact full-key match: sharing a household (same household id) but differing in telephone yields
12	 * different keys and is allowed. Not a pipeline step, so it exposes plain helpers.
13	 */
14	public final class IdentityKey {
15	
16	    private IdentityKey() {
17	    }
18	
19	    /** The identity key of an existing or freshly built owner. */
20	    public static String forOwner(Owner owner) {
21	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
22	    }
23	
24	    /**
25	     * Builds the identity key from its parts: the telephone in canonical E.164 form (see
26	     * {@link TelephoneNormalizer}), the email lower-cased or empty when absent or blank (see
27	     * {@link EmailNormalizer}) and the household id or empty when absent, separated by '|'.
28	     */
29	    public static String of(String telephone, String email, String householdId) {
30	        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|" + orEmpty(householdId);
31	    }
32	
33	    private static String normalizeTelephone(String telephone) {
34	        String e164 = TelephoneNormalizer.toE164(telephone);
35	        return e164 == null ? orEmpty(telephone) : e164;
36	    }
37	
38	    private static String normalizeEmail(String email) {
39	        return (email == null || email.isBlank()) ? "" : EmailNormalizer.normalize(email);
40	    }
41	
42	    private static String orEmpty(String value) {
43	        return value == null ? "" : value;
44	    }
45	}
