1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Canonical household comparison shared by the create pipeline: {@link AssignHousehold} uses it to
9	 * decide whether two owners share a household and to derive the shared household id (which in turn
10	 * feeds the household part of the {@link IdentityKey duplicate key}). A household is identified by last
11	 * name plus address: the last name is compared
12	 * case-insensitively with runs of whitespace collapsed to a single space and outer whitespace trimmed,
13	 * and the address is compared in its canonical form (see {@link AddressNormalizer}). Not a pipeline
14	 * step, so it is free to expose plain helpers.
15	 */
16	public final class HouseholdNormalizer {
17	
18	    private HouseholdNormalizer() {
19	    }
20	
21	    /**
22	     * The stable household identifier derived from an owner's last name and address. Owners with
23	     * equal {@link #key(String, String) keys} share the same id, and the id never changes for a given
24	     * household, so it can be recomputed for late joiners rather than stored and looked up.
25	     */
26	    public static String id(String lastName, String address) {
27	        return "H-" + sha256hex(key(lastName, address)).substring(0, 12).toUpperCase();
28	    }
29	
30	    private static String sha256hex(String value) {
31	        try {
32	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
33	            StringBuilder hex = new StringBuilder(digest.length * 2);
34	            for (byte b : digest) {
35	                hex.append(String.format("%02x", b));
36	            }
37	            return hex.toString();
38	        }
39	        catch (NoSuchAlgorithmException e) {
40	            throw new IllegalStateException("SHA-256 not available", e);
41	        }
42	    }
43	
44	    /**
45	     * Builds the canonical household key for an owner from its last name and address. Two owners
46	     * belong to the same household when their keys are equal. Either field may be {@code null}, which
47	     * normalizes to an empty token.
48	     */
49	    public static String key(String lastName, String address) {
50	        // '\n' separates the fields so that a boundary shift (e.g. "ab"+"c" vs "a"+"bc") cannot forge a
51	        // collision; it never appears in a normalized value.
52	        return normalizeName(lastName) + "\n" + AddressNormalizer.normalize(address);
53	    }
54	
55	    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
56	    private static String normalizeName(String value) {
57	        if (value == null) {
58	            return "";
59	        }
60	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
61	    }
62	}
