185	        this.pets = new HashSet<>(pets);
186	    }
187	
188	    public void addPet(Pet pet) {
189	        getPetsInternal().add(pet);
190	        pet.setOwner(this);
191	    }
192	
193	    /**
194	     * Return the Pet with the given name, or null if none found for this Owner.
195	     *
196	     * @param name to test
197	     * @return true if pet name is already in use
198	     */
199	    public Pet getPet(String name) {
200	        return getPet(name, false);
201	    }
202	
203	    /**
204	     * Return the Pet with the given name, or null if none found for this Owner.
205	     *
206	     * @param name to test
207	     * @return true if pet name is already in use
208	     */
209	    public Pet getPet(String name, boolean ignoreNew) {
210	        name = name.toLowerCase();
211	        for (Pet pet : getPetsInternal()) {
212	            if (!ignoreNew || !pet.isNew()) {
213	                String compName = pet.getName();
214	                compName = compName.toLowerCase();
215	                if (compName.equals(name)) {
216	                    return pet;
217	                }
218	            }
219	        }
220	        return null;
221	    }
