2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Rejects a create request whose derived {@link IdentityKey identity key} exactly equals an existing
10	 * owner's — the single consolidated duplicate check that replaces the separate telephone, email and
11	 * household checks. Runs after the telephone and email are normalized and the household id assigned
12	 * (see {@link AssignHousehold}), so the built owner already carries its final key parts. Because the
13	 * telephone is part of the key, two members of one household with different telephones have distinct
14	 * keys and are both allowed; only a full-key match is a 409 via {@link DuplicateIdentityException}.
15	 */
16	public class EnsureUniqueIdentity {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws DuplicateIdentityException {
20	        String identityKey = IdentityKey.forOwner(owner);
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (identityKey.equals(IdentityKey.forOwner(existing))) {
23	                throw new DuplicateIdentityException(identityKey);
24	            }
25	        }
26	    }
27	}
