4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many owners the new owner's household will hold once this create completes — the new
9	 * owner plus every existing owner sharing the same household (same last name and address, compared
10	 * via {@link HouseholdNormalizer}). Runs before {@link SaveOwner}, so the new
11	 * owner is not yet persisted and is counted explicitly. Mutates the built {@link Owner} in place.
12	 */
13	public class CountHousehold {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String key = HouseholdNormalizer.key(owner.getLastName(), owner.getAddress());
17	        int members = 1;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (key.equals(HouseholdNormalizer.key(existing.getLastName(), existing.getAddress()))) {
20	                members++;
21	            }
22	        }
23	        owner.setHouseholdSize(members);
24	    }
25	}
