3	import java.util.Map;
4	
5	/**
6	 * Canonical address normalization shared by the create pipeline: {@link NormalizeAddress} stores and
7	 * returns the normalized form and {@link HouseholdNormalizer} compares addresses by it. Not a pipeline
8	 * step, so it is free to expose plain helpers.
9	 */
10	public final class AddressNormalizer {
11	
12	    /** Common street-type abbreviations expanded to their full word (keys are already upper-cased). */
13	    private static final Map<String, String> ABBREVIATIONS = Map.of(
14	            "ST", "STREET",
15	            "RD", "ROAD",
16	            "AVE", "AVENUE");
17	
18	    private AddressNormalizer() {
19	    }
20	
21	    /**
22	     * Normalizes an address to its canonical stored/compared form: outer whitespace trimmed, internal
23	     * runs of whitespace collapsed to a single space, upper-cased, and common street-type
24	     * abbreviations expanded as whole words ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code
25	     * ROAD}, {@code AVE}&rarr;{@code AVENUE}). A {@code null} or blank address normalizes to an empty
26	     * string. Idempotent: normalizing an already-normalized address returns it unchanged.
27	     */
28	    public static String normalize(String address) {
29	        if (address == null) {
30	            return "";
31	        }
32	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
33	        if (collapsed.isEmpty()) {
34	            return "";
35	        }
36	        String[] tokens = collapsed.split(" ");
37	        StringBuilder result = new StringBuilder(collapsed.length());
38	        for (int i = 0; i < tokens.length; i++) {
39	            if (i > 0) {
40	                result.append(' ');
41	            }
42	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
43	        }
44	        return result.toString();
45	    }
46	}
